#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_depth3D;
uniform float amzp_depthSpeed;
uniform float amzp_strandCount;
uniform float amzp_waveAmplitude;
uniform float amzp_waveFrequency;
uniform float amzp_waveSpeed;
uniform float amzp_lineThickness;
uniform float amzp_flowDirection;
uniform float amzp_strandSpread;
uniform float amzp_organicAmount;
uniform float amzp_organicFrequency;
uniform float amzp_useTarget;
uniform float amzp_targetX;
uniform float amzp_targetY;
uniform float amzp_showCrosshair;
uniform float amzp_crosshairBoxSize;
uniform float amzp_distortAmount;
uniform float amzp_distortFrequency;
uniform float amzp_distortSpeed;
uniform float amzp_glitchSpeed;
uniform float amzp_glitchNoise;
uniform float amzp_glitchBias;
uniform float amzp_glitchWidth;
uniform float amzp_invertOnGlitch;
uniform float amzp_showBorder;
uniform float amzp_showTicks;
uniform float amzp_tickDensity;
uniform float amzp_tickPosition;
uniform float amzp_uiBrightness;
uniform float amzp_grainAmount;
uniform float amzp_glowAmount;
uniform float amzp_overSource;
uniform float amzp_intensity;
    float toRad(float d){ return 3.14159 * d / 180.0; }
    float hash12(float2 p){
        float3 p3 = fract(float3(p.xyx) * 0.1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float2 randVec(float2 p){
        float a = hash12(p);
        a *= 2.0*3.14159;
        a += time;
        return float2(sin(a), cos(a));
    }
    float perlin(float2 p){
        float2 f = fract(p);
        float2 s = smoothstep(0.0, 1.0, f);
        float2 i = floor(p);
        float a = dot(randVec(i), f);
        float b = dot(randVec(i+float2(1,0).xy), f-float2(1,0).xy);
        float c = dot(randVec(i+float2(1,0).yx), f-float2(1,0).yx);
        float d = dot(randVec(i+float2(1,0).xx), f-float2(1,0).xx);
        return mix(mix(a, b, s.x), mix(c, d, s.x), s.y)/0.707107;
    }
    float fbm(float2 p){
        float a = 0.5;
        float r = 0.0;
        for(int i = 0; i < 8; i++){
            r += a*perlin(p);
            a *= 0.5;
            p *= 2.0;
        }
        return r;
    }
    float square(float2 p, float2 s){
        float2 d = abs(p)-s;
        return length(max(d, 0.0)) + min(0.0, max(d.x,d.y));
    }
    void amzRender(){
        float2 res = screen.zw;
        float2 fragCoord = amzScreenNorm() * res;
        float iTime = time;
        float px = 1.0/res.y;
        float px2 = 2.0*px;
        float2 uv = fragCoord.xy/res.y;
        uv.y = 1.0-uv.y;
        float ar = res.x/res.y;
        uv -= float2(ar/2.0,0.5);
        float uxy = uv.x+uv.y;
        float n = fbm(float2(amzp_distortFrequency*uv.y, amzp_distortSpeed*iTime));
        float g = amzp_glitchNoise*n + amzp_glitchBias + sin(amzp_glitchSpeed*iTime);
        uv.x += amzp_distortAmount * smoothstep(amzp_glitchWidth, 0.0, abs(g))*n;
        float s = perlin(float2(0.3*iTime));
        float2 p = float2(perlin(float2(0.5*iTime)), 0.5*perlin(float2(-iTime)))*0.5*(res.xy - float2(300, 300))/res.y;
        p.y -= 0.1*sin(6.0*p.x+iTime);
        if((amzp_useTarget>0.5)){
            float2 m = float2(amzp_targetX, amzp_targetY);
            m.x = clamp(ar*0.35*m.x, -ar*0.35, ar*0.35);
            m.y = clamp(0.25*m.y, -0.25, 0.25);
            p = m;
        }
        float a = smoothstep(-0.5, -0.1, s)*smoothstep(mix(0.01, 0.9, smoothstep(-0.5, 0.5, s)), 0.0, length(uv-p));
        float ang = toRad(amzp_flowDirection);
        float ca = cos(ang), sa = sin(ang);
        float along = uv.x*ca + uv.y*sa;
        float across = -uv.x*sa + uv.y*ca;
        float r = 0.0;
        for(float i = 1.0; i <= 16.0; i++){
            if(i > amzp_strandCount) break;
            float z = 0.5 + 0.5*sin(i*1.3 + iTime*0.8*amzp_depthSpeed);
            float f = across;
            f += amzp_waveAmplitude*sin(amzp_waveFrequency*along + iTime*amzp_waveSpeed + a*sin(i+iTime)*1.25*cos(amzp_waveFrequency*along + 0.5*i));
            f += amzp_organicAmount * 0.12 * perlin(float2(along*amzp_organicFrequency + i*2.0, iTime*0.6));
            f += (i - (amzp_strandCount+1.0)*0.5) * amzp_strandSpread * 0.04;
            f += (z - 0.5) * 0.08 * amzp_depth3D;
            float thick = amzp_lineThickness * mix(1.0, mix(0.55, 1.6, z), amzp_depth3D);
            float bright = mix(1.0, mix(0.6, 1.35, z), amzp_depth3D);
            r += (thick/abs(f)) * bright;
        }
        float ob = square(uv, 0.5*float2(0.9*ar,1.0-0.1*ar));
        float border = 1.5*smoothstep(px2, -px2, abs(ob));
        if(!(amzp_showBorder>0.5)) border = 0.0;
        float ms = step(ob, -0.005) * smoothstep(0.01, 0.005, abs(abs(uv.y)-amzp_tickPosition*(1.0-0.1*ar)));
        ms *= smoothstep(px2, px, fract(uv.x*amzp_tickDensity)/amzp_tickDensity);
        if(!(amzp_showTicks>0.5)) ms = 0.0;
        float ui = max(border, ms);
        float cr = smoothstep(px2, 0.0, abs(min(abs(uv.x-p.x), abs(uv.y-p.y))));
        cr = max(cr, 3.0*smoothstep(px2, -px2, abs(square(uv-p, (0.1+smoothstep(-0.25, 0.5, s))*float2(amzp_crosshairBoxSize)))));
        cr *= smoothstep(0.0, -0.1, ob);
        if(!(amzp_showCrosshair>0.5)) cr = 0.0;
        ui = max(ui, cr);
        r = max(r, amzp_uiBrightness*ui);
        r *= mix(1.0, 2.0*pow(0.5+0.5*n, 2.0), amzp_glowAmount);
        r *= mix(1.0, 0.5+0.5*hash12(fragCoord.xy+iTime), amzp_grainAmount);
        r = clamp(r, 0.0, 1.0);
        float val = (amzp_invertOnGlitch>0.5) ? mix(r, pow(1.0-r, 3.0), smoothstep(-0.025, 0.025, g)) : r;
        float3 scan = float3(val);
        float3 orig = amzTexture(0, amzScreenNorm()).rgb;
        float3 outc = (amzp_overSource>0.5) ? (1.0 - (1.0-orig)*(1.0-scan)) : scan;
        amzOutput = float4(mix(orig, outc, amzp_intensity), 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

